/// <summary>
/// Each type of price component (Trade Agreement, Margin Component, etc uses different table,
/// therefore needs a variety of caches.
/// </summary>
internal abstract class GUPPriceEngineAbstractLineCache
{

    // List of a <GUPPriceEngineAbstractLine>.
    protected List lineList = null;

    // Key = Datasource name (table name or provider class name).
    // Value = GUPPricingAttributeDatasourceAggregationObject
    protected Map pricingAttributeDatasourceMap = null;

    protected TransDate cachedDate;

}

Method.Source:
/// <summary>
/// Do NOT modify the returned list.
/// </summary>
/// <returns>An (suppose to be) immutable list. </returns>
public List parmLineList()
{
    return this.lineList;
}

/// <summary>
/// Load one pricing attribute group (either header or line), and values for its every attribute.
/// </summary>
/// <param name = "_pricingRule">For table join.</param>
/// <param name = "_pricingAttributeGroup">Group information.</param>
/// <returns>GUPTradeAgreementAttributeGroupObject.</returns>
protected GUPPriceEngineAttributeGroupObject createAttributeGroupObject(GUPPricingRule _pricingRule,
    GUPPricingAttributeGroup _pricingAttributeGroup)
{
    // Pricing rule has no attribute group -- header or line applies to all salesLine.
    if (_pricingRule.PriceAttributeGroup == 0)
    {
        return null;
    }

    GUPPriceEngineAttributeGroupObject attributeGroup = new GUPPriceEngineAttributeGroupObject(_pricingRule, _pricingAttributeGroup);
    attributeGroup = this.loadRuleConditionValue(_pricingRule, attributeGroup);
    return attributeGroup;
}

/// <summary>
/// Load attribute class, priority, and values for each pricing attribute.
/// </summary>
/// <param name = "_gupPricingRule">For table join.</param>
/// <param name = "_attributeGroupObject">Group information.</param>
/// <returns>GUPTradeAgreementAttributeGroupObject.</returns>
private GUPPriceEngineAttributeGroupObject loadRuleConditionValue(GUPPricingRule _gupPricingRule, GUPPriceEngineAttributeGroupObject _attributeGroupObject)
{
    GUPPricingRule gupPricingRule;
    GUPPricingRuleCondition ruleCondition;
    GUPPricingAttributeLink attributeLink;
    GUPPricingAttributeLink attributeLinkFromGroup;
    GUPPricingAttributeGroup attributeGroup;

    List attributeConditionValueList = new List(Types::AnyType);
    while select ruleCondition
        join attributeLink
            where ruleCondition.ConditionAttribute == attributeLink.RecId
                && _gupPricingRule.RecId == ruleCondition.RuleId
        outer join attributeGroup
            where attributeGroup.Name == ruleCondition.ConditionValue
                && (attributeLink.Source == GUPPricingAttributeSource::CustomerPriceGroup
                    ||  attributeLink.Source == GUPPricingAttributeSource::ProductPriceGroup)
        outer join attributeLinkFromGroup
        order by attributeLink.Priority desc, attributeLinkFromGroup.Priority desc
            where attributeLinkFromGroup.PriceAttributeGroup == attributeGroup.RecId
    {
        // A customer / product price attribute group without value (i.e. specific structure) is ignored.
        if ((attributeLink.Source == GUPPricingAttributeSource::CustomerPriceGroup
                    ||  attributeLink.Source == GUPPricingAttributeSource::ProductPriceGroup)
            && (!attributeLinkFromGroup))
        {
            continue;
        }

        str conditionValue = (attributeLinkFromGroup) ? attributeLinkFromGroup.DefaultValue : ruleCondition.ConditionValue;
        GUPPricingAttributeLink actualLink = (attributeLinkFromGroup) ? attributeLinkFromGroup : attributeLink;

        GUPPriceEngineConditionValueObject valueObject = new GUPPriceEngineConditionValueObject(conditionValue, actualLink);

        // Stored with priority from largest (most specific) to smallest (most general).
        attributeConditionValueList.addEnd(valueObject);
    }

    _attributeGroupObject.parmAttributeConditionValueList(attributeConditionValueList);
    return _attributeGroupObject;
}

/// <summary>
/// Find datasource(s) and field(s) required for ONE line, and add them to the map.
/// </summary>
/// <param name = "_line">A price computation line, either Trade Agreement, Margin Component, or something else.</param>
/// <param name = "_attributeGroup">The pricing attribute group (header or line) bound to that line.</param>
/// <param name = "_pricingAttributeDatasourceMap">Map stores ALL relations.</param>
protected void loadLineRequiredFields(GUPPriceEngineAbstractLine _line,
    GUPPriceEngineAttributeGroupObject _attributeGroup,
    Map _pricingAttributeDatasourceMap)
{
    if(_attributeGroup == null)
    {
        return;
    }

    // List<GUPPricingRuleConditionValueObject>.
    List conditionValueList = _attributeGroup.parmAttributeConditionValueList();
    ListEnumerator conditionValueEnumerator = conditionValueList.getEnumerator();

    while (conditionValueEnumerator.moveNext())
    {
        GUPPriceEngineConditionValueObject conditionValue = conditionValueEnumerator.current();

        GUPPriceEngineDatasourceAggregationObject datasource = this.loadDatasourceObject(
                conditionValue, _pricingAttributeDatasourceMap);

        // See GUPAbstractPricingAttribute..getAttributeFieldIdentifier();
        // Table field name for class-based pricing attribute, Name+Typename for EcoResAttribute.
        str dataFieldId = conditionValue.parmPricingAttribute().getAttributeFieldIdentifier();

        datasource.addDataFieldRelation(dataFieldId, _line);
    }
}

/// <summary>
/// Find datasource and field for ONE pricing attribute, and put it into the map.
/// </summary>
/// <param name = "_conditionValue">One pricing attribute, including</param>
/// <param name = "_pricingAttributeDatasourceMap">Map stores ALL relations.</param>
/// <returns>A record of map of the related table / ecoResAttributeProvider.</returns>
private GUPPriceEngineDatasourceAggregationObject loadDatasourceObject(
    GUPPriceEngineConditionValueObject _conditionValue,
    Map _pricingAttributeDatasourceMap)
{
    str datasourceId = _conditionValue.parmPricingAttribute().getQueryBuilderDatasourceIdentifier();

    GUPPriceEngineDatasourceAggregationObject datasourceObject;
    if (_pricingAttributeDatasourceMap.exists(datasourceId))
    {
        datasourceObject = _pricingAttributeDatasourceMap.lookup(datasourceId);
    }
    else
    {
        datasourceObject = new GUPPriceEngineDatasourceAggregationObject(datasourceId, _conditionValue.parmPricingAttribute());
        _pricingAttributeDatasourceMap.add(datasourceId, datasourceObject);
    }

    return datasourceObject;
}
